/**
 * 音量控制插件
 */

import type { MpvPlugin } from '../../core/types/plugin';
import { ControlPlugin, ControlPluginOptions } from '../base/ControlPlugin';
import { volumeIcon, volumeMutedIcon } from '../../renderer/icons';
import styles from './styles.css?inline';

export interface VolumePluginOptions extends ControlPluginOptions {
    position?: 'left' | 'right';
    order?: number;
}

export const VolumePlugin: MpvPlugin<VolumePluginOptions> = {
    name: 'volume',
    version: '1.0.0',
    styles,

    install(player, options = {}) {
        return new VolumeManager(player, {
            position: options.position ?? 'left',
            order: options.order ?? 20,
        });
    },
};

export class VolumeManager extends ControlPlugin<Required<VolumePluginOptions>> {
    readonly name = 'volume';

    // DO NOT initialize these fields here! JavaScript field initializers run AFTER super(),
    // which would reset values set during createEl() back to null.
    private volumeBtn!: HTMLButtonElement | null;
    private volumeSlider!: HTMLElement | null;
    private volumeTrackFilled!: HTMLElement | null;
    private volumeHandle!: HTMLElement | null;

    private isDragging = false;

    protected createEl(): HTMLElement {
        const container = document.createElement('div');
        container.className = 'vp-volume-container';
        container.innerHTML = `
            <button class="vp-btn vp-volume-btn" title="靜音 (M)">
                <span class="vp-icon-volume">${volumeIcon}</span>
                <span class="vp-icon-muted">${volumeMutedIcon}</span>
            </button>
            <div class="vp-volume-slider">
                <div class="vp-volume-track">
                    <div class="vp-volume-track-filled"></div>
                    <div class="vp-volume-handle"></div>
                </div>
            </div>
        `;

        this.volumeBtn = container.querySelector('.vp-volume-btn');
        this.volumeSlider = container.querySelector('.vp-volume-slider');
        this.volumeTrackFilled = container.querySelector('.vp-volume-track-filled');
        this.volumeHandle = container.querySelector('.vp-volume-handle');

        this.bindEvents();
        this.updateUI();

        return container;
    }

    private bindEvents(): void {
        // 音量按鈕點擊切換靜音
        if (this.volumeBtn) {
            this.on(this.volumeBtn, 'click', (e) => {
                e.stopPropagation();
                this.toggleMute();
            });
        }

        // 音量滑桿拖拽
        if (this.volumeSlider) {
            this.on(this.volumeSlider, 'mousedown', (e) => {
                e.stopPropagation();
                this.isDragging = true;
                this.updateVolumeFromMouse(e);
            });
        }

        this.on(document, 'mousemove', (e) => {
            if (!this.isDragging) return;
            this.updateVolumeFromMouse(e);
        });

        this.on(document, 'mouseup', () => {
            this.isDragging = false;
        });

        // 監聯音量變化
        this.onPlayer('volumechange', () => this.updateUI());
    }

    private updateVolumeFromMouse(e: MouseEvent): void {
        const track = this.volumeSlider?.querySelector('.vp-volume-track');
        if (!track) return;
        const rect = track.getBoundingClientRect();
        const percent = Math.max(0, Math.min(1, (e.clientX - rect.left) / rect.width));
        this.player.volume = percent;
    }

    private toggleMute(): void {
        this.player.muted = !this.player.muted;
    }

    private updateUI(): void {
        const volume = this.player.volume;
        const isMuted = this.player.muted || volume === 0;

        this.el?.classList.toggle('muted', isMuted);

        if (this.volumeTrackFilled) {
            this.volumeTrackFilled.style.width = `${volume * 100}%`;
        }
        if (this.volumeHandle) {
            this.volumeHandle.style.left = `${volume * 100}%`;
        }
    }
}

